import ctypes
import os

# Load the GSL libraries
ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

# Define the function prototype
# double gsl_cdf_gamma_P(const double x, const double a, const double b);
gsl.gsl_cdf_gamma_P.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_double]
gsl.gsl_cdf_gamma_P.restype = ctypes.c_double

def gamma_cdf(x, a, b):
    """Compute the CDF of the gamma distribution using GSL."""
    if a <= 0 or b <= 0:
        raise ValueError("Shape parameter 'a' and scale parameter 'b' must be positive.")
    if x < 0:
        return 0.0  # CDF is 0 for negative x in gamma distribution
    return gsl.gsl_cdf_gamma_P(x, a, b)

def assert_test():
    # Test cases
    assert abs(gamma_cdf(5.0, 2.0, 2.0) - 0.7127025048163548) < 1e-9, "Test case 2 failed"
    assert abs(gamma_cdf(0.5, 1.0, 1.0) - 0.3934693402873666) < 1e-9, "Test case 3 failed"
    assert abs(gamma_cdf(0.0, 1.0, 1.0) - 0.0) < 1e-9, "Test case 4 failed"
    assert gamma_cdf(-1.0, 2.0, 2.0) == 0.0, "Test case 6 failed (negative x)"
    try:
        gamma_cdf(2.0, -1.0, 2.0)
    except ValueError as e:
        assert str(e) == "Shape parameter 'a' and scale parameter 'b' must be positive.", "Test case 7 failed (negative a)"
    try:
        gamma_cdf(2.0, 2.0, -1.0)
    except ValueError as e:
        assert str(e) == "Shape parameter 'a' and scale parameter 'b' must be positive.", "Test case 8 failed (negative b)"

if __name__ == "__main__":
    assert_test()
    print("All tests passed.")
